begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(20);
insert into auth.users(id,email) values('99300000-0000-4000-8000-000000000001','tax-preparer@example.test'),('99300000-0000-4000-8000-000000000002','tax-reviewer@example.test');
insert into public.app_users(id,email,full_name) values('99300000-0000-4000-8000-000000000001','tax-preparer@example.test','Tax preparer'),('99300000-0000-4000-8000-000000000002','tax-reviewer@example.test','Tax reviewer');
insert into public.orgs(id,name,slug) values('99300000-0000-4000-8000-000000000003','Tax workpaper acceptance','tax-workpaper-acceptance');
insert into public.roles(id,key,label,scope) values('99300000-0000-4000-8000-000000000004','tax_workpaper_acceptance','Tax acceptance','org');
insert into public.memberships(org_id,user_id,role_id) values('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000004'),('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000002','99300000-0000-4000-8000-000000000004');
create function pg_temp.tax_base() returns jsonb language sql as $$select jsonb_build_object('basis','cash','version',1,'start_date','2026-01-01','end_date','2026-12-31','net_income_cents',0,'source_revision',public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'))$$;
insert into public.files(id,org_id,file_name,storage_path,mime_type,size_bytes,checksum,uploaded_by,category,source) values('99300000-0000-4000-8000-000000000010','99300000-0000-4000-8000-000000000003','Original tax calculation.txt','99300000-0000-4000-8000-000000000003/tax/original.txt','text/plain',3,repeat('a',64),'99300000-0000-4000-8000-000000000001','financials','upload');
insert into public.doc_versions(id,org_id,file_id,version_number,file_name,storage_path,mime_type,size_bytes,checksum) select '99300000-0000-4000-8000-000000000011',org_id,id,1,file_name,storage_path,mime_type,size_bytes,checksum from public.files where id='99300000-0000-4000-8000-000000000010';
update public.files set current_version_id='99300000-0000-4000-8000-000000000011' where id='99300000-0000-4000-8000-000000000010';
create function pg_temp.attachment_proof() returns jsonb language sql as $$select jsonb_build_object('version',1,'org_id',org_id,'file_id',id,'document_version_id',current_version_id,'file_name',file_name,'storage_path',storage_path,'mime_type',mime_type,'size_bytes',size_bytes,'checksum',checksum) from public.files where id='99300000-0000-4000-8000-000000000010'$$;
create function pg_temp.attachment_lines() returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('id','99300000-0000-4000-8000-000000000012','kind','permanent','amount_cents',100,'description','Reviewed permanent difference','evidence_reference','Tax source calculation','evidence_file_id','99300000-0000-4000-8000-000000000010','evidence_snapshot',pg_temp.attachment_proof()))$$;
create function pg_temp.attachment_prepare(key text,lines jsonb default pg_temp.attachment_lines()) returns uuid language sql as $$select public.prepare_books_tax_workpaper('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','2026-01-01','2026-12-31',repeat('a',64),pg_temp.tax_base(),lines,key,null)$$;
select ok(not has_function_privilege('authenticated','public.protect_books_tax_document_evidence()','execute') and (select prosecdef from pg_proc where oid='public.protect_books_tax_document_evidence()'::regprocedure),'internal document guard has no browser execute grant');
select throws_like($$select pg_temp.attachment_prepare('tax-no-frozen-attachment-key',jsonb_set(pg_temp.attachment_lines(),'{0,evidence_snapshot}','null'))$$,'%frozen scoped version%','new attached workpapers require frozen identity');
select throws_like($$select pg_temp.attachment_prepare('tax-changed-size-key',jsonb_set(pg_temp.attachment_lines(),'{0,evidence_snapshot,size_bytes}','4'))$$,'%metadata changed%','stale size rejected under file lock');
select throws_like($$select pg_temp.attachment_prepare('tax-foreign-path-key',jsonb_set(pg_temp.attachment_lines(),'{0,evidence_snapshot,storage_path}','"outside/tax.txt"'))$$,'%frozen scoped version%','cross-organization object path rejected');
select lives_ok($$select pg_temp.attachment_prepare('tax-frozen-attachment-key')$$,'prepare frozen scoped attachment');
select throws_like($$update public.files set checksum=repeat('b',64) where id='99300000-0000-4000-8000-000000000010'$$,'%original object metadata is immutable%','original object checksum cannot be rewritten in place');
select throws_like($$update public.files set size_bytes=4 where id='99300000-0000-4000-8000-000000000010'$$,'%original object metadata is immutable%','original object size cannot be rewritten in place');

select throws_like($$update public.doc_versions set checksum=repeat('b',64) where id='99300000-0000-4000-8000-000000000011'$$,'%version evidence is immutable%','referenced version checksum cannot change');
select throws_like($$delete from public.doc_versions where id='99300000-0000-4000-8000-000000000011'$$,'%version evidence is immutable%','referenced version cannot be deleted');
select throws_like($$delete from public.files where id='99300000-0000-4000-8000-000000000010'$$,'%document history cannot be deleted%','referenced document cannot be deleted');
insert into public.doc_versions(id,org_id,file_id,version_number,file_name,storage_path,mime_type,size_bytes,checksum) select '99300000-0000-4000-8000-000000000013',org_id,id,2,'Revised tax calculation.txt','99300000-0000-4000-8000-000000000003/tax/revised.txt',mime_type,5,repeat('b',64) from public.files where id='99300000-0000-4000-8000-000000000010';
select lives_ok($$update public.files set current_version_id='99300000-0000-4000-8000-000000000013',file_name='Revised tax calculation.txt',storage_path='99300000-0000-4000-8000-000000000003/tax/revised.txt',size_bytes=5,checksum=repeat('b',64) where id='99300000-0000-4000-8000-000000000010'$$,'live file may advance to another version');
set local role service_role;
select lives_ok($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from public.books_tax_adjustment_workpapers where idempotency_key='tax-frozen-attachment-key'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed original immutable attachment version')$$,'review retains original identity despite live version advance');
reset role;
select is((select lines->0->'evidence_snapshot'->>'storage_path' from public.books_tax_adjustment_workpapers where idempotency_key='tax-frozen-attachment-key'),'99300000-0000-4000-8000-000000000003/tax/original.txt','original attachment path retained after review');
select throws_like($$update public.books_tax_adjustment_workpapers set lines=jsonb_set(lines,'{0,evidence_snapshot,checksum}',to_jsonb(repeat('b',64))) where idempotency_key='tax-frozen-attachment-key'$$,'%evidence is immutable%','saved attachment digest cannot be rewritten');
select throws_like($$update public.files set org_id='99300000-0000-4000-8000-000000000099' where id='99300000-0000-4000-8000-000000000010'$$,'%history identity is immutable%','referenced file cannot move to another organization');
insert into public.files(id,org_id,file_name,storage_path,mime_type,size_bytes,checksum,uploaded_by,category,source) values('99300000-0000-4000-8000-000000000014','99300000-0000-4000-8000-000000000003','Unreferenced document.txt','99300000-0000-4000-8000-000000000003/tax/unreferenced.txt','text/plain',3,repeat('a',64),'99300000-0000-4000-8000-000000000001','financials','upload');
select set_config('request.jwt.claims','{"sub":"99300000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$delete from public.files where id='99300000-0000-4000-8000-000000000014'$$,'ordinary authorized document deletion can consult internal tax guard');
reset role;
select is((select count(*) from public.files where id='99300000-0000-4000-8000-000000000014'),0::bigint,'unreferenced document actually deleted under browser role');
insert into public.files(id,org_id,file_name,storage_path,mime_type,size_bytes,checksum,uploaded_by,category,source) values('99300000-0000-4000-8000-000000000015','99300000-0000-4000-8000-000000000003','Legacy tax source.txt','99300000-0000-4000-8000-000000000003/tax/legacy.txt','text/plain',3,repeat('c',64),'99300000-0000-4000-8000-000000000001','financials','upload');
select lives_ok($$select pg_temp.attachment_prepare('tax-legacy-path-reference-key',jsonb_build_array(jsonb_build_object('id','99300000-0000-4000-8000-000000000017','kind','permanent','amount_cents',1,'description','Reviewed legacy document difference','evidence_reference','Legacy source calculation','evidence_file_id','99300000-0000-4000-8000-000000000015','evidence_snapshot',(select jsonb_build_object('version',1,'org_id',org_id,'file_id',id,'document_version_id',current_version_id,'file_name',file_name,'storage_path',storage_path,'mime_type',mime_type,'size_bytes',size_bytes,'checksum',checksum) from public.files where id='99300000-0000-4000-8000-000000000015'))))$$,'legacy file can freeze exact bytes without inventing a version identity');
select throws_like($$update public.files set storage_path='99300000-0000-4000-8000-000000000003/tax/legacy-revised.txt' where id='99300000-0000-4000-8000-000000000015'$$,'%Missing retained original tax document version%','advancing legacy file requires retaining original object metadata');
insert into public.doc_versions(id,org_id,file_id,version_number,file_name,storage_path,mime_type,size_bytes,checksum) select '99300000-0000-4000-8000-000000000016',org_id,id,1,file_name,storage_path,mime_type,size_bytes,checksum from public.files where id='99300000-0000-4000-8000-000000000015';
select throws_like($$delete from public.doc_versions where id='99300000-0000-4000-8000-000000000016'$$,'%version evidence is immutable%','backfilled version is protected by frozen object path even when original version ID was null');
-- Mutex contention needs two authenticated sessions, which a non-superuser
-- pgTAP run cannot open; it runs in RACE-01 (scripts/books-acceptance/race/).
select * from finish();
rollback;
